#!/usr/bin/env python3
"""Render the nightly STATUS page from the report JSONs."""

import argparse
import datetime
import glob
import json
import pathlib
import sys


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="conformance/NIGHTLY-STATUS.md")
    args = ap.parse_args()
    files = sorted(glob.glob("reports/nightly-*.json"))
    lines = [
        "# Nightly corpus status",
        "",
        "Generated by the nightly-corpus workflow; raw reports under `reports/nightly-*.json`.",
        "",
    ]
    if files:
        d = json.load(open(files[-1]))
        c = d.get("counts", {})
        lines += [
            "**Last run:** %s — %s PASS / %s FAIL / %s SKIP / %s FILL"
            % (pathlib.Path(files[-1]).name, c.get("PASS", 0), c.get("FAIL", 0), c.get("SKIP", 0), c.get("FILL", 0)),
            "",
        ]
    lines += ["| date | PASS | FAIL | SKIP | FILL |", "|---|---|---|---|---|"]
    for f in files[-30:]:
        d = json.load(open(f))
        c = d.get("counts", {})
        lines.append(
            "| %s | %s | %s | %s | %s |"
            % (
                pathlib.Path(f).stem.replace("nightly-", ""),
                c.get("PASS", 0),
                c.get("FAIL", 0),
                c.get("SKIP", 0),
                c.get("FILL", 0),
            )
        )
    lines.append("")
    lines.append("_generated %s UTC_" % datetime.datetime.utcnow().strftime("%Y-%m-%d %H:%M"))
    pathlib.Path(args.out).write_text("\n".join(lines) + "\n")
    print("%s written from %d report(s)" % (args.out, len(files)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
